 counts=collections.Counter(); signatures=collections.defaultdict(list)
 for p in sorted((Path('results/python')/conf/'P07/raw').glob('*.json')):
  d=json.loads(p.read_text()); counts[d['run']['mode']]+=1
  a=d['stages'][0]['attempts'][-1]
  sig={'stdout':a['stdout'],'observe':a['observe']['raw'],'execution':[c['execution_state']['states'] for c in a['computations']], 'faults':d['harness_faults'], 'notes':d['notes']}
  signatures[json.dumps(sig,sort_keys=True)].append((d['run']['instance'],d['run']['mode']))
 print(conf,dict(counts))
 for sig,runs in signatures.items():
  if conf=='extended': print(runs, sig)
  elif len(set(m for i,m in runs))"'!=3: print('"'POSSIBLE MODE DIFF',runs,sig)
PY"

